    o=[[0]*w for _ in range(h)]
    Hr={}  # (r,c)->color for horiz segments
    Vr={}
    for r in range(h):
        for cc in range(w):
            v=g[r][cc]
            # horizontal run membership
            hr = cc>0 and g[r][cc-1]==v or cc<w-1 and g[r][cc+1]==v
            vr = r>0 and g[r-1][cc]==v or r<h-1 and g[r+1][cc]==v
            if hr and not vr: Hr[(r,cc)]=v
            elif vr and not hr: Vr[(r,cc)]=v
            elif hr and vr: pass  # ambiguous corner
    for (r,c),v in Hr.items():
        # find run
        rs=runs(g[r])
        for k,s,e in rs:
            if s<=c<=e:
                lo,hi=s,e
                for cc in range(lo,hi+1): o[r][cc]=v
                break
    for (r,c),v in Vr.items():
        col=[g[rr][c] for rr in range(h)]
        bs=runs(col)
        best=None
        for k,s,e in bs:
            d=(e-s+1)-abs(k-r)  # longer run + closer penalty
            if best is None or d<best[0]: best=(d,k,s,e)
        _,s,e=best[1],best[2],best[3]
        lo,hi=max(r,s),min(r,e)
        # fill full column
        for rr in range(h): o[rr][c]=v
    return o

