def gapease(g):
    h=len(g); w=len(g[0]); g=[r[:] for r in g]
    for _ in range(w):
        changed=False
        for r in range(h):
            for c in range(1,w-1):
                if g[r][c]==0 and g[r][c-1]==g[r][c+1]!=0 and g[r][c]!=g[r][c-1]:
                    g[r][c]=g[r][c-1]; changed=True
        if not changed: break
    return g

# mechanism A: rays in 4 dirs, simultaneous, lower source wins collisions
def sim_A(g):
    g=[r[:] for r in g]
    H,W=len(g),len(g[0])
    import collections
    changes=True
    while changes:
        changes=False
        # gather pending paints per cell from each direction
        paint=collections.defaultdict(collections.Counter)
        for r in range(H):
            for c in range(W):
                if g[r][c]!=0:
                    # up
                    rr,cc=r-1,c
                    while 0<=rr<H and g[rr][cc]==0:
                        paint[(rr,cc)][g[r][c]]+=1; rr-=1
                    # down
                    rr,cc=r+1,c
                    while 0<=rr<H and g[rr][cc]==0:
                        paint[(rr,cc)][g[r][c]]+=1; rr+=1
                    # left
                    rr,cc=r,c-1
                    while 0<=cc<W and g[rr][cc]==0:
                        paint[(rr,cc)][g[r][c]]+=1; cc-=1
                    # right
                    rr,cc=r,c+1
                    while 0<=cc<W and g[rr][cc]==0:
                        paint[(rr,cc)][g[r][c]]+=1; cc+=1
        for (r,c),cnt in paint.items():
            if cnt[g[r][c]]>0 and sum(cnt.values())==cnt[g[r][c]]:
                g[r][c]=g[r][c]  # nothing
        # apply: a cell gets color if all its rays agree; conflicts -> ?
        for (r,c),cnt in paint.items():
            if len(cnt)>1: continue
            col=next(iter(cnt))
            if g[r][c]==0: g[r][c]=col; changes=True
    return g

