                    c+=1
                if c-W<=0: break
                c0=c-1
                while c<W and g[r][c]==v:
                    c+=1
                if c-c0>=2: s.append((c0,c-1))
            else: c+=1
        if s: bars.append((g[r][s[0][0]],r,s))
    # gap-fill bars
    for v,r,segs in bars:
        for a,b in segs:
            for cc in range(a+1,b):
                if g[r][cc]==0: g[r][cc]=v
    # beam column: gap col if unique gap else longest-adjacent-segment col
    def beam_col(v,r,segs):
        gaps=[(a+1,b) for a,b in segs if b-a>=1 and all(g[r][x]==0 for x in range(a+1,b))]
        if len(gaps)==1: return gaps[0][0]
        # longest adjacent segment col
        best=None
        for a,b in segs:
            L=b-a+1
            cand=a if (a==0 or g[r][a-1]==0) else None
            cand2=b+1 if (b+1<W and g[r][b+1]==0) else None
            if cand is not None and (best is None or L>Lbest if False else True):
                pass
        # pick col with longest segment adjacent
        scores=[]
        for a,b in segs:
            L=b-a+1
            sc=L
            if a==0 or g[r][a-1]==0: sc+=1
            if b+1<W and g[r][b+1]==0: sc+=1
            scores.append((sc,a))
        scores.sort(reverse=True)
        return scores[0][1]
    beams=[]
    for v,r,segs in bars:
        bc=beam_col(v,r,segs)
        beams.append((r,v,bc))
    # place beams top-down, upward until blocked
    grid=[row[:] for row in g]
    for r,v,bc in sorted(beams):
        rr=r-1
        while rr>=0 and grid[rr][bc]==0:
            grid[rr][bc]=v; rr-=1
    # strays: cells not in any bar and not 0
    stray_cells=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=0:
                # is it in a bar?
                inb=False
                for _,rr,segs in bars:
                    if rr==r and any(a<=c<=b for a,b in segs): inb=True
                if not inb: stray_cells.append((r,c,g[r][c]))
    for (sr,sc,sval) in stray_cells:
        # extend up until orthogonally adjacent to a colored cell in same col
        r=sr
        while r>0 and grid[r-1][sc]==0:
            r-=1
        # mark extension cells (keep original)
        ext=[rr for rr in range(r,sr)]
        for rr in ext: grid[rr][sc]=sval
    return grid
